1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"os"
8		"unicode/utf8"
9	)
10	
11	// EvalReason is the machine-readable outcome of a flag evaluation.
12	type EvalReason string
13	
14	const (
15		EvalDisabled EvalReason = "disabled"
16		EvalRule     EvalReason = "rule"
17		EvalDefault  EvalReason = "default"
18	)
19	
20	// Condition is one predicate over an evaluation context.
21	type Condition struct {
22		Attribute string
23		Op        string
24		// strVal 用于 eq；inVal 用于 in（至少一项）。
25		strVal string
26		inVal  []string
27	}
28	
29	// Rule groups conditions that must all hold; on match the flag takes Value.
30	type Rule struct {
31		ID         string
32		Value      bool
33		Conditions []Condition
34	}
35	
36	// Flag is one feature toggle with its default and ordered rules.
37	type Flag struct {
38		Key     string
39		Enabled bool
40		Default bool
41		Rules   []Rule
42	}
43	
44	// Config is a validated feature flag configuration.
45	type Config struct {
46		Flags []Flag
47	}
48	
49	// EvalResult is the deterministic outcome of evaluating one flag.
50	type EvalResult struct {
51		Key    string     `json:"key"`
52		Value  bool       `json:"value"`
53		Reason EvalReason `json:"reason"`
54		RuleID *string    `json:"ruleId"`
55	}
56	
57	// Equals reports whether two evaluation results are identical.
58	func (r EvalResult) Equals(other EvalResult) bool {
59		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
60			return false
61		}
62		if (r.RuleID == nil) != (other.RuleID == nil) {
63			return false
64		}
65		if r.RuleID != nil && *r.RuleID != *other.RuleID {
66			return false
67		}
68		return true
69	}
70	
71	// Context is a validated map of attribute names to string values.
72	type Context struct {
73		values map[string]string
74	}
75	
76	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
77	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
78	func LoadConfig(path string) (*Config, error) {
79		raw, err := os.ReadFile(path)
80		if err != nil {
81			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
82		}
83		return ParseConfig(raw)
84	}
85	
86	// LoadContext reads and validates a UTF-8 JSON context file.
87	func LoadContext(path string) (*Context, error) {
88		raw, err := os.ReadFile(path)
89		if err != nil {
90			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
91		}
92		return ParseContext(raw)
93	}
94	
95	// ParseConfig parses a config document from JSON bytes with strict typing.
96	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
97	func ParseConfig(raw []byte) (*Config, error) {
98		if !utf8.Valid(raw) {
99			return nil, fmt.Errorf("config: file is not valid UTF-8")
100		}
101		var doc any
102		if err := json.Unmarshal(raw, &doc); err != nil {
103			return nil, fmt.Errorf("config: invalid JSON: %w", err)
104		}
105		root, ok := doc.(map[string]any)
106		if !ok {
107			return nil, fmt.Errorf("config: top level must be a JSON object")
108		}
109		flagsRaw, present := root["flags"]
110		if !present {
111			return nil, fmt.Errorf("config.flags: field is required")
112		}
113		if flagsRaw == nil {
114			return nil, fmt.Errorf("config.flags: must be an array, got null")
115		}
116		flagsArr, ok := flagsRaw.([]any)
117		if !ok {
118			return nil, fmt.Errorf("config.flags: must be an array")
119		}
120		cfg := &Config{}
121		seenKeys := map[string]int{}
122		for i, fr := range flagsArr {
123			flag, err := parseFlag(fr, i)
124			if err != nil {
125				return nil, err
126			}
127			if prev, dup := seenKeys[flag.Key]; dup {
128				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
129			}
130			seenKeys[flag.Key] = i
131			cfg.Flags = append(cfg.Flags, flag)
132		}
133		return cfg, nil
134	}
135	
136	// ParseContext parses an attribute-name -> string context object; it may be empty.
137	func ParseContext(raw []byte) (*Context, error) {
138		if !utf8.Valid(raw) {
139			return nil, fmt.Errorf("context: file is not valid UTF-8")
140		}
141		var doc any
142		if err := json.Unmarshal(raw, &doc); err != nil {
143			return nil, fmt.Errorf("context: invalid JSON: %w", err)
144		}
145		root, ok := doc.(map[string]any)
146		if !ok {
147			return nil, fmt.Errorf("context: top level must be a JSON object")
148		}
149		ctx := &Context{values: make(map[string]string, len(root))}
150		for k, v := range root {
151			s, ok := v.(string)
152			if !ok {
153				return nil, fmt.Errorf("context.%s: value must be a string", k)
154			}
155			ctx.values[k] = s
156		}
157		return ctx, nil
158	}
159	
160	// Get looks up an attribute; an empty string is a legal value.
161	func (c *Context) Get(attribute string) (string, bool) {
162		if c == nil {
163			return "", false
164		}
165		v, ok := c.values[attribute]
166		return v, ok
167	}
168	
169	// Find returns the flag with the given key, or nil if absent.
170	func (c *Config) Find(key string) *Flag {
171		if c == nil {
172			return nil
173		}
174		for i := range c.Flags {
175			if c.Flags[i].Key == key {
176				return &c.Flags[i]
177			}
178		}
179		return nil
180	}
181	
182	// Evaluate deterministically evaluates a flag against a context.
183	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
184	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
185	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
186	func (f *Flag) Evaluate(ctx *Context) EvalResult {
187		if !f.Enabled {
188			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
189		}
190		for i := range f.Rules {
191			rule := &f.Rules[i]
192			if rule.matches(ctx) {
193				id := rule.ID
194				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
195			}
196		}
197		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
198	}
199	
200	func (r *Rule) matches(ctx *Context) bool {
201		for i := range r.Conditions {
202			if !r.Conditions[i].matches(ctx) {
203				return false
204			}
205		}
206		return true
207	}
208	
209	func (c Condition) matches(ctx *Context) bool {
210		v, present := ctx.Get(c.Attribute)
211		if !present {
212			return false
213		}
214		switch c.Op {
215		case "eq":
216			return v == c.strVal
217		case "in":
218			for _, candidate := range c.inVal {
219				if v == candidate {
220					return true
221				}
222			}
223			return false
224		default:
225			// 解析阶段已拒绝未知运算符，防御性处理。
226			return false
227		}
228	}
229	
230	// MarshalResult renders the result as a single compact JSON object.
231	func MarshalResult(r EvalResult) ([]byte, error) {
232		var buf bytes.Buffer
233		enc := json.NewEncoder(&buf)
234		enc.SetEscapeHTML(false)
235		if err := enc.Encode(r); err != nil {
236			return nil, err
237		}
238		return bytes.TrimRight(buf.Bytes(), "\n"), nil
239	}
240	
241	// --- strict parsing helpers -------------------------------------------------
242	
243	func parseFlag(raw any, index int) (Flag, error) {
244		loc := fmt.Sprintf("config.flags[%d]", index)
245		obj, ok := raw.(map[string]any)
246		if !ok {
247			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
248		}
249		key, err := requireNonEmptyString(obj, "key", loc)
250		if err != nil {
251			return Flag{}, err
252		}
253		enabled, err := requireBool(obj, "enabled", loc)
254		if err != nil {
255			return Flag{}, err
256		}
257		def, err := requireBool(obj, "default", loc)
258		if err != nil {
259			return Flag{}, err
260		}
261		rulesArr, err := requireArrayField(obj, "rules", loc)
262		if err != nil {
263			return Flag{}, err
264		}
265		flag := Flag{Key: key, Enabled: enabled, Default: def}
266		seenRules := map[string]int{}
267		for ri, rv := range rulesArr {
268			rule, err := parseRule(rv, index, ri)
269			if err != nil {
270				return Flag{}, err
271			}
272			if prev, dup := seenRules[rule.ID]; dup {
273				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
274			}
275			seenRules[rule.ID] = ri
276			flag.Rules = append(flag.Rules, rule)
277		}
278		return flag, nil
279	}
280	
281	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
282		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
283		obj, ok := raw.(map[string]any)
284		if !ok {
285			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
286		}
287		id, err := requireNonEmptyString(obj, "id", loc)
288		if err != nil {
289			return Rule{}, err
290		}
291		value, err := requireBool(obj, "value", loc)
292		if err != nil {
293			return Rule{}, err
294		}
295		condsArr, err := requireArrayField(obj, "conditions", loc)
296		if err != nil {
297			return Rule{}, err
298		}
299		if len(condsArr) == 0 {
300			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
301		}
302		rule := Rule{ID: id, Value: value}
303		for ci, cv := range condsArr {
304			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
305			if err != nil {
306				return Rule{}, err
307			}
308			rule.Conditions = append(rule.Conditions, cond)
309		}
310		return rule, nil
311	}
312	
313	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
314		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
315		obj, ok := raw.(map[string]any)
316		if !ok {
317			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
318		}
319		attribute, err := requireNonEmptyString(obj, "attribute", loc)
320		if err != nil {
321			return Condition{}, err
322		}
323		op, err := requireNonEmptyString(obj, "op", loc)
324		if err != nil {
325			return Condition{}, err
326		}
327		valueField, err := requireField(obj, "value", loc)
328		if err != nil {
329			return Condition{}, err
330		}
331		cond := Condition{Attribute: attribute, Op: op}
332		switch op {
333		case "eq":
334			s, ok := valueField.(string)
335			if !ok {
336				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
337			}
338			cond.strVal = s
339		case "in":
340			arr, ok := valueField.([]any)
341			if !ok {
342				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
343			}
344			if len(arr) == 0 {
345				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
346			}
347			for ii, item := range arr {
348				s, ok := item.(string)
349				if !ok {
350					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
351				}
352				cond.inVal = append(cond.inVal, s)
353			}
354		default:
355			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
356		}
357		return cond, nil
358	}
359	
360	func requireField(obj map[string]any, name, loc string) (any, error) {
361		v, ok := obj[name]
362		if !ok {
363			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
364		}
365		if v == nil {
366			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
367		}
368		return v, nil
369	}
370	
371	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
372		v, err := requireField(obj, name, loc)
373		if err != nil {
374			return nil, err
375		}
376		arr, ok := v.([]any)
377		if !ok {
378			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
379		}
380		return arr, nil
381	}
382	
383	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
384		v, err := requireField(obj, name, loc)
385		if err != nil {
386			return "", err
387		}
388		s, ok := v.(string)
389		if !ok {
390			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
391		}
392		if s == "" {
393			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
394		}
395		return s, nil
396	}
397	
398	func requireBool(obj map[string]any, name, loc string) (bool, error) {
399		v, err := requireField(obj, name, loc)
400		if err != nil {
401			return false, err
402		}
403		b, ok := v.(bool)
404		if !ok {
405			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
406		}
407		return b, nil
408	}
