package payflow

import (
	"strings"
	"testing"
)

// TestDuplicateFieldsRejected verifies that any JSON object declaring the
// same field name twice is rejected, in both config and context, at every
// nesting level.
func TestDuplicateFieldsRejected(t *testing.T) {
	cases := []struct {
		name string
		raw  string
		want string // error must contain this substring
	}{
		// --- config: every object level ---
		{"config top-level flags", `{"flags":[],"flags":[]}`, `duplicate field "flags"`},
		{"config flag enabled", `{"flags":[{"key":"f","enabled":true,"enabled":false,"default":false,"rules":[]}]}`, `duplicate field "enabled"`},
		{"config flag key", `{"flags":[{"key":"f","key":"g","enabled":true,"default":false,"rules":[]}]}`, `duplicate field "key"`},
		{"config flag default", `{"flags":[{"key":"f","enabled":true,"default":false,"default":true,"rules":[]}]}`, `duplicate field "default"`},
		{"config flag rules", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],"rules":[]}]}`, `duplicate field "rules"`},
		{"config rule id", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","id":"s","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]}]}`, `duplicate field "id"`},
		{"config rule value", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"value":false,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]}]}`, `duplicate field "value"`},
		{"config rule conditions", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[],"conditions":[]}]}]}`, `duplicate field "conditions"`},
		{"config condition attribute", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[{"attribute":"a","attribute":"b","op":"eq","value":"x"}]}]}]}`, `duplicate field "attribute"`},
		{"config condition op", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","op":"in","value":"x"}]}]}]}`, `duplicate field "op"`},
		{"config condition value", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x","value":"y"}]}]}]}`, `duplicate field "value"`},
		// --- locations carry array indices ---
		{"config dup in second flag", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[]},{"key":"g","enabled":true,"enabled":false,"default":false,"rules":[]}]}`, `config.flags[1]`},
		{"config dup in second rule", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]},{"id":"r2","id":"r3","value":false,"conditions":[{"attribute":"a","op":"eq","value":"y"}]}]}]}`, `config.flags[0].rules[1]`},
		{"config dup in second condition", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"},{"attribute":"b","op":"eq","op":"in","value":"y"}]}]}]}`, `config.flags[0].rules[0].conditions[1]`},
		// --- nested objects inside additional fields ---
		{"config dup in flag extra object", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],"meta":{"x":1,"x":2}}]}`, `config.flags[0].meta`},
		{"config dup in deeply nested extra", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],"a":{"b":{"c":1,"c":2}}}]}`, `config.flags[0].a.b`},
		{"config dup in condition value object", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":{"x":1,"x":2}}]}]}]}`, `config.flags[0].rules[0].conditions[0].value`},
		// --- name comparison: decoded strings, case-sensitive, no trimming ---
		{"config unicode escape collision", "{\"flags\":[{\"key\":\"f\",\"enabled\":true,\"en\\u0061bled\":false,\"default\":false,\"rules\":[]}]}", `duplicate field "enabled"`},
		{"config same value still errors", `{"flags":[{"key":"f","enabled":true,"enabled":true,"default":false,"rules":[]}]}`, `duplicate field "enabled"`},
		{"config case differs is fine", `{"flags":[{"key":"f","Enabled":true,"enabled":false,"default":false,"rules":[]}]}`, ``},
		{"config leading space not trimmed", `{"flags":[{"key":"f","enabled":true," enabled":false,"default":false,"rules":[]}]}`, ``},
		{"config trailing space not trimmed", `{"flags":[{"key":"f","enabled":true,"enabled ":false,"default":false,"rules":[]}]}`, ``},
		// --- unselected / disabled flags are not exempt ---
		{"config dup in unselected flag", `{"flags":[{"key":"good","enabled":true,"default":false,"rules":[]},{"key":"bad","enabled":true,"enabled":false,"default":false,"rules":[]}]}`, `config.flags[1]`},
		{"config dup in disabled flag", `{"flags":[{"key":"off","enabled":false,"enabled":true,"default":false,"rules":[]}]}`, `config.flags[0]`},
		{"config dup in rule of disabled flag", `{"flags":[{"key":"off","enabled":false,"default":false,"rules":[{"id":"r","id":"s","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]}]}`, `config.flags[0].rules[0]`},
		// --- first duplicate in document order wins ---
		{"config first dup in file order", `{"flags":[{"key":"f","enabled":true,"enabled":false,"default":false,"rules":[{"id":"r","id":"s","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]}]}`, `duplicate field "enabled"`},
		// --- context ---
		{"context top-level", `{"plan":"pro","plan":"free"}`, `context`},
		{"context nested object", `{"plan":"pro","attrs":{"a":"1","a":"2"}}`, `context.attrs`},
		{"context nested in array", `{"items":[{"k":"1","k":"2"}]}`, `context.items[0]`},
		{"context unicode escape", "{\"plan\":\"pro\",\"pl\\u0061n\":\"free\"}", `duplicate field "plan"`},
		{"context same value still errors", `{"plan":"pro","plan":"pro"}`, `duplicate field "plan"`},
		{"context case differs is fine", `{"Plan":"pro","plan":"free"}`, ``},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseConfig([]byte(tc.raw))
			if strings.HasPrefix(tc.name, "context ") {
				_, err = ParseContext([]byte(tc.raw))
			}
			if tc.want == "" {
				if err != nil {
					t.Fatalf("expected no error, got %v", err)
				}
				return
			}
			if err == nil {
				t.Fatalf("expected error containing %q, got nil", tc.want)
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %q, want substring %q", err.Error(), tc.want)
			}
			if !strings.Contains(err.Error(), "duplicate") {
				t.Fatalf("error must state the ambiguity, got %q", err.Error())
			}
		})
	}
}

// TestDuplicateFieldsAcrossObjectsAllowed confirms that the same field name
// in two different objects, and duplicate elements of arrays, are legal.
func TestDuplicateFieldsAcrossObjectsAllowed(t *testing.T) {
	// Same key field in two flags, same id in two rules, same attribute in
	// two conditions — all legal.
	cfg := `{"flags":[
		{"key":"f","enabled":true,"default":false,"rules":[
			{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x"}]}]},
		{"key":"f","enabled":true,"default":false,"rules":[
			{"id":"r","value":false,"conditions":[{"attribute":"a","op":"eq","value":"y"}]}]}]}`
	c, err := ParseConfig([]byte(cfg))
	if err != nil {
		t.Fatalf("same name across objects should be legal: %v", err)
	}
