	}
}

// TestNoDuplicatesMeansNoRegression confirms the happy paths still parse.
func TestNoDuplicatesMeansNoRegression(t *testing.T) {
	cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
